INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('68bfdebc-e08e-4eca-b3a9-27d1160b6c90', 'c3c3c3c3-3030-4000-8000-000000000003', 22, 'Dia 22 — Atenção', 'Semana 4: Integrar', '{"pch": "Cuidado com o modo como voc\u00eas ouvem\u2026 Aten\u00e7\u00e3o \u00e9 a ora\u00e7\u00e3o mais b\u00e1sica.", "verse": "Lc 8,18", "lectio": "Leia Lc 8,16-18. A l\u00e2mpada e a aten\u00e7\u00e3o.", "practice": "Pratique aten\u00e7\u00e3o plena numa atividade simples: comer, caminhar, respirar.", "question": "No que voc\u00ea tem prestado aten\u00e7\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;